fn frame(t: i32) {
    host::display::clear(0x000000);
    let w: i32 = host::display::width();
    let px: i32 = w / 2;
    let py: i32 = 40;
    let len: i32 = 170;
    let mut g: i32 = 24;
    while g <= 104 {
        let gx: i32 = px + (len * host::math::cos(g)) / 256;
        let gy: i32 = py + (len * host::math::sin(g)) / 256;
        host::display::set_pixel(gx, gy, 0x333333);
        g = g + 2;
    }
    let swing: i32 = (40 * host::math::sin(t * 2)) / 256;
    let a: i32 = 64 + swing;
    let bx: i32 = px + (len * host::math::cos(a)) / 256;
    let by: i32 = py + (len * host::math::sin(a)) / 256;
    host::display::draw_line(px, py, bx, by, 0xaaaaaa);
    host::display::fill_rect(px - 3, py - 3, 6, 6, 0x888888);
    host::display::fill_rect(bx - 8, by - 8, 16, 16, 0xffcc33);
    host::display::present();
}
